def rgb(r,g,b):
    return r + g*256 + b*65536

vals = {
 "GREEN (146,208,80)": (rgb(146,208,80), 5287310),
 "PINK (255,199,206)": (rgb(255,199,206), 13556223),
 "LTGREEN (198,239,206)": (rgb(198,239,206), 13561542),
 "ORANGE (255,192,0)": (rgb(255,192,0), 49152),
 "DRAFT (242,242,242)": (rgb(242,242,242), 15921906),
 "VOIDED (217,217,217)": (rgb(217,217,217), 14277081),
 "MISSED (166,166,166)": (rgb(166,166,166), 10921638),
}
for k,(correct,claimed) in vals.items():
    status = "OK" if correct==claimed else "MISMATCH diff=%d" % (claimed-correct)
    print(f"{k}: correct={correct} claimed={claimed} -> {status}")

def decode(v):
    b = (v >> 16) & 0xFF
    g = (v >> 8) & 0xFF
    r = v & 0xFF
    return (r,g,b)

for k,(correct,claimed) in vals.items():
    print(k, "claimed decodes to RGB", decode(claimed))
